import java.util.*;

public class TextEditing {
    private static String toUnderscoreForm(String s) {
        StringBuilder t = new StringBuilder();
        boolean inside = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                inside = true;
            } else if (ch == ')') {
                inside = false;
                t.append('_');
            } else if (!inside) {
                t.append(ch);
            }
        }
        return t.toString();
    }

    public static int maxLength(String s) {
        StringTokenizer st = new StringTokenizer(toUnderscoreForm(s), "_");
        int max = 0;
        while (st.hasMoreTokens()) {
            String token = st.nextToken();
            if (token.length() > max) {
                max = token.length();
            }
        }
        return max;
    }

    public static int count(String s) {
        return new StringTokenizer(s, "_").countTokens();
    }

    public static int words(String s) {
        int c = 0;
        StringBuilder t = new StringBuilder();
        boolean inside = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                inside = true;
            } else if (ch == ')') {
                inside = false;
                c += count(t.toString());
                t.setLength(0);
            }
            if (inside && ch != '(') {
                t.append(ch);
            }
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        System.out.println(maxLength(s) + " " + words(s));
    }
}
